    INSERT INTO lessons (chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES
      (v_chapter,v_c_lena,v_c_raha,'Erstes Hallo','اولین سلام','Lena begegnet Raha im Hausflur.','لنا در راهرو با رها آشنا می‌شود.','story','berlin_new_start',1,1,420,1,'validated',JSON_OBJECT('pedagogicalRole','exposure')),
      (v_chapter,v_c_lena,v_c_raha,'Wie heißt du?','اسمت چیه؟','Raha übt Namen und passende Begrüßungen.','رها نام و سلام مناسب را تمرین می‌کند.','story','berlin_new_start',2,1,420,2,'validated',JSON_OBJECT('pedagogicalRole','explicit_form')),
      (v_chapter,v_c_lena,v_c_raha,'Noch einmal vorstellen','معرفی دوباره','Raha ruft Begrüßung und Namen ohne direkte Vorlage ab.','رها سلام و نام را بدون الگوی مستقیم بازیابی می‌کند.','story','berlin_new_start',3,1,420,3,'validated',JSON_OBJECT('pedagogicalRole','retrieval')),
      (v_chapter,v_c_lena,v_c_raha,'Im Café','در کافه','Raha stellt sich in einem neuen Kontext selbstständig vor.','رها در موقعیت تازه کافه مستقل معرفی می‌کند.','story','berlin_new_start',4,1,420,4,'validated',JSON_OBJECT('pedagogicalRole','mastery'));
